// Exercici 5 - Valida la mostra que envia l'AtomS3
// Sortida 1: mostra correcta (va al fitxer)   Sortida 2: error (va directe a la resposta)

// 1. Llegim el cos. Arriba en brut (text o Buffer) perque volem
//    controlar nosaltres l'error de JSON mal escrit (400)
let cos = msg.payload;
if (Buffer.isBuffer(cos)) {
    cos = cos.toString("utf8");
}
let dades = cos;
if (typeof cos === "string") {
    try {
        dades = JSON.parse(cos);
    } catch (e) {
        dades = undefined;
    }
}

// 2. Ha de ser un objecte JSON. Si no -> 400 Bad Request
if (dades === null || typeof dades !== "object" || Array.isArray(dades)) {
    msg.statusCode = 400;
    msg.payload = { error: "JSON invalid" };
    return [null, msg];
}

// 3. Hi han de ser tots els camps. Si en falta algun -> 422
const camps = ["id", "temperatura", "humitat", "rssi", "temps_activitat"];
const falten = camps.filter(c => dades[c] === undefined || dades[c] === null || dades[c] === "");
if (falten.length > 0) {
    msg.statusCode = 422;
    msg.payload = { error: "Falten camps", falten: falten };
    return [null, msg];
}

// 4. Temperatura dins d'un rang raonable: el del DHT22 (-40 a 80 C). Si no -> 422
const t = Number(dades.temperatura);
if (!Number.isFinite(t) || t < -40 || t > 80) {
    msg.statusCode = 422;
    msg.payload = { error: "Temperatura fora de rang", temperatura: dades.temperatura };
    return [null, msg];
}

// 5. Tot correcte: afegim la marca de temps en format ISO 8601
dades.rebut = new Date().toISOString();
msg.payload = JSON.stringify(dades);   // una linia de text per al fitxer JSONL
return [msg, null];

// La mostra ja s'ha desat al fitxer -> 201 Created
msg.statusCode = 201;
msg.payload = { resultat: "desat" };
return msg;
